ram_inline.patch:
diff --git a/src/emu/cpu/include/cpu/aot/code_cache.h b/src/emu/cpu/include/cpu/aot/code_cache.h
index 892a39e86..cb824a058 100644
--- a/src/emu/cpu/include/cpu/aot/code_cache.h
+++ b/src/emu/cpu/include/cpu/aot/code_cache.h
@@ -66,7 +66,21 @@ namespace eka2l1::arm::aot {
         }
         // Called only after the outer boundary selected trusted bytes and the
         // original layout. Mapping/lifetime checks still apply on every lookup.
-        block *find_trusted_original(std::uint32_t pc_mode, core &cpu);
+#if defined(_MSC_VER)
+        __forceinline
+#else
+        __attribute__((always_inline))
+#endif
+        block *find_trusted_original(std::uint32_t pc_mode, core &cpu) {
+            const auto generation = cpu.code_mapping_generation
+                ? cpu.code_mapping_generation->load(std::memory_order_acquire) : 0;
+            const auto k = key(cpu.code_address_space, pc_mode);
+            auto *entry = recent_[recent_index(k)];
+            if (entry && entry->live && entry->key == k && generation
+                && entry->mapping_source == cpu.code_mapping_generation
+                && entry->mapping_generation == generation) return entry;
+            return find_trusted_slow(pc_mode, cpu);
+        }

     private:
         template<bool TrustBytes>
@@ -134,6 +148,7 @@ namespace eka2l1::arm::aot {
         template<bool TrustBytes>
         block *find_original_impl(std::uint32_t pc_mode, core &cpu);
         block *find_original(std::uint32_t pc_mode, core &cpu);
+        block *find_trusted_slow(std::uint32_t pc_mode, core &cpu);
         void reject_recent(std::uint64_t k, block &entry);

     public:
diff --git a/src/emu/cpu/src/aot/code_compare.cpp b/src/emu/cpu/src/aot/code_compare.cpp
index e28ac9ac8..a440aa6a2 100644
--- a/src/emu/cpu/src/aot/code_compare.cpp
+++ b/src/emu/cpu/src/aot/code_compare.cpp
@@ -19,7 +19,7 @@ namespace eka2l1::arm::aot {
     validated_code_cache::block *validated_code_cache::find_original(std::uint32_t pc_mode, core &cpu) {
         return find_original_impl<false>(pc_mode, cpu);
     }
-    validated_code_cache::block *validated_code_cache::find_trusted_original(std::uint32_t pc_mode, core &cpu) {
+    validated_code_cache::block *validated_code_cache::find_trusted_slow(std::uint32_t pc_mode, core &cpu) {
         return find_original_impl<true>(pc_mode, cpu);
     }
     template<bool TrustBytes>
